%% ════════════════════════════════════════════════════════════════════════════
%% Fig 0 — Combined: all filters on one axes
%% ════════════════════════════════════════════════════════════════════════════
figure('Name','A2 — All filters combined','Position',[60 60 900 680]);
ax0 = axes('Position',[0.13 0.13 0.82 0.74]);
hold on;

yline(ax0, TRUE_ROLL, '--', 'Color',cTrue, 'LineWidth',1.8, 'HandleVisibility','off');
for k = 1:6
    plot(ax0, T, filter_data{k}, '-', 'Color',filter_colors{k}, 'LineWidth',filter_lw(k));
end
plot(ax0, T, r_ekf9, '-', 'Color',cEKF9, 'LineWidth',1.8);
xline(ax0, 9, '--', 'Color',cMadg, 'LineWidth',1.2, 'HandleVisibility','off');
text(ax0, 0.3, 31.5, 'True roll = 30°', 'FontSize',21, 'Color',cTrue);
text(ax0, 9.2, 5, 'Madgwick converges', 'FontSize',18, 'Color',cMadg, 'FontAngle','italic');

set(ax0, 'XLim',[0 20], 'YLim',[0 36], 'Box','off', ...
         'YGrid','on', 'XGrid','off', 'GridAlpha',0.25, 'GridLineStyle','--');
xlabel(ax0, 'Time  (s)', 'FontSize',25);
ylabel(ax0, 'Estimated roll  (°)', 'FontSize',25);
legend(ax0, filter_names, 'FontSize',18, 'Location','southeast', 'Box','off');
hold off;

%% ════════════════════════════════════════════════════════════════════════════
%% Figs 1–7 — One figure per filter
%% ════════════════════════════════════════════════════════════════════════════
for k = 1:7
    figure('Name', ['A2 — ' filter_names{k}], ...
           'Position', [60+offsets(k)  60+offsets(k)  900  680]);
    ax = axes('Position',[0.13 0.13 0.82 0.74]);
    hold on;

    yline(ax, TRUE_ROLL, '--', 'Color',cTrue, 'LineWidth',1.8, 'HandleVisibility','off');
    plot(ax, T, filter_data{k}, '-', 'Color',filter_colors{k}, 'LineWidth',filter_lw(k));

    text(ax, 0.3, 31.5, 'True roll = 30°', 'FontSize',21, 'Color',cTrue);

    set(ax, 'XLim',[0 20], 'YLim',[0 36], 'Box','off', ...
            'YGrid','on', 'XGrid','off', 'GridAlpha',0.25, 'GridLineStyle','--');
    xlabel(ax, 'Time  (s)', 'FontSize',25);
    ylabel(ax, 'Estimated roll  (°)', 'FontSize',25);
    legend(ax, {filter_names{k}}, 'FontSize',21, 'Location','southeast', 'Box','off');
    hold off;
end


