for i = 1:7
    bar(ax3, i, means3(i), 0.6, 'FaceColor',cols3{i}, 'EdgeColor','k', ...
        'LineWidth',0.5, 'FaceAlpha',0.72);
end

errorbar(ax3, 1:7, means3, stds3, 'k', 'LineStyle','none', 'CapSize',7, 'LineWidth',1.2);

